// Typed access to the static JSON generated by scripts/build_data.py from the FINAL competition outputs.
// See DATA_MAPPING.md for the field-by-field provenance. Nothing here is computed except where marked "derived".
import top10Raw from '../data/top10.json'
import eligibleRaw from '../data/eligible.json'
import modelRaw from '../data/model.json'
import sensRaw from '../data/sensitivity_lists.json'
import valRaw from '../data/pressure_validation.json'
import shareRaw from '../data/pressure_share.json'
import bootRaw from '../data/bootstrap.json'
import provRaw from '../data/provenance.json'

export type Side = 'bat' | 'bowl'

export interface Player {
  side: Side
  rank: number
  player_id: number
  name: string
  n_h: number // high-pressure balls
  m_h: number // matches with >=1 high-pressure ball
  S_h_raw: number // raw pressure residual per 100 balls
  S_h: number // shrunk (empirical Bayes) pressure residual per 100 balls
  W_h_raw: number
  S_l: number // baseline per 100 balls
  R_raw: number
  C_raw: number
  zH: number
  zR: number
  zC: number
  final: number
  top10_prob: number
  rank_median: number
  rank_p05: number
  rank_p95: number
  final_p05: number
  final_p95: number
  appearances: number
  n_press_IPL: number
  S_raw_IPL: number | null
  n_press_T20I: number
  S_raw_T20I: number | null
  // descriptive evidence (not scored)
  strike_rate_press?: number
  strike_rate_base?: number
  economy_press?: number
  economy_base?: number
  dot_pct_press: number
  dot_pct_base: number
  boundary_pct_press: number
  boundary_pct_base: number
  dismissals_press?: number
  dismissals_base?: number
  runs_press?: number
  wickets_press?: number
  wickets_base?: number
  wides_nb_pct_press?: number
  legal_balls_press?: number
  [k: string]: number | string | null | undefined
}

const raw = top10Raw as unknown as Record<Side, Omit<Player, 'side'>[]>
// Bootstrap rank quantiles are interpolated in the CSV (e.g. 57.2); we display whole ranks for the 90% range and the median to one
// decimal (ranks are integers; a median of 11.5 means two adjacent ranks were equally common). Documented in DATA_MAPPING.md.
const tidy = <T extends { rank_p05: number; rank_p95: number; rank_median: number }>(p: T): T => ({ ...p, rank_p05: Math.round(p.rank_p05), rank_p95: Math.round(p.rank_p95), rank_median: Math.round(p.rank_median * 10) / 10 })
export const PLAYERS: Record<Side, Player[]> = {
  bat: raw.bat.map((p) => tidy({ ...p, side: 'bat' as Side } as any) as Player),
  bowl: raw.bowl.map((p) => tidy({ ...p, side: 'bowl' as Side } as any) as Player),
}
export const ALL_PLAYERS: Player[] = [...PLAYERS.bat, ...PLAYERS.bowl]
export const playerById = (id: number, side?: Side) => ALL_PLAYERS.find((p) => p.player_id === id && (!side || p.side === side))

export interface Eligible { pid: number; name: string; n_h: number; m_h: number; S_h_raw: number; S_h: number; S_l: number; final: number; rank: number; top10_prob: number | null }
export const ELIGIBLE = eligibleRaw as unknown as Record<Side, Eligible[]>

export const MODEL = modelRaw as any
export const SENS = sensRaw as unknown as { names: Record<string, string> } & Record<Side, { label: string; overlap: number; n_elig: number; top10: number[] }[]>
export const VALIDATION = valRaw as any[]
export const SHARE = shareRaw as { innings: number; phase: string; balls: number; high_share_pct: number }[]
export const BOOT = bootRaw as unknown as Record<Side, { pid: number; name: string; top10_prob: number; rank_median: number; rank_p05: number; rank_p95: number }[]>
export const PROVENANCE = provRaw as Record<string, string>

// ---- units / labels ---------------------------------------------------------------------------------------------
export const UNIT: Record<Side, string> = {
  bat: 'runs per 100 balls above the expectation for the same situation',
  bowl: 'runs per 100 balls saved against the expectation for the same situation',
}
export const SIDE_LABEL: Record<Side, string> = { bat: 'Batters', bowl: 'Bowlers' }
export const SIDE_COLOR: Record<Side, string> = { bat: 'var(--seam)', bowl: 'var(--outfield)' }

// ---- formatting --------------------------------------------------------------------------------------------------
export const f0 = (x: number) => Math.round(x).toLocaleString('en-GB')
export const f1 = (x: number) => x.toFixed(1)
export const f2 = (x: number) => x.toFixed(2)
export const signed = (x: number, d = 1) => (x > 0 ? '+' : x < 0 ? '−' : '') + Math.abs(x).toFixed(d)
export const pct0 = (x: number) => `${Math.round(x * 100)}%`

// ---- derived (documented) ----------------------------------------------------------------------------------------
/** Contribution of each component to the final rating: final = 0.60*zH + 0.25*zR + 0.15*zC (verified to 1e-9 in tests). */
export const WEIGHTS = { H: 0.6, R: 0.25, C: 0.15 }
export const contrib = (p: Player) => ({ H: WEIGHTS.H * p.zH, R: WEIGHTS.R * p.zR, C: WEIGHTS.C * p.zC })
/** A rank is called "uncertain" when its 90% bootstrap rank range spans more than 25 ranks. */
export const rankSpan = (p: Player) => p.rank_p95 - p.rank_p05
export const certainty = (p: Player): 'stable' | 'moderate' | 'uncertain' =>
  p.top10_prob >= 0.8 && rankSpan(p) <= 25 ? 'stable' : p.top10_prob >= 0.5 ? 'moderate' : 'uncertain'
export const CERTAINTY_LABEL = { stable: 'Stable', moderate: 'Moderately supported', uncertain: 'Uncertain' } as const
export const COMP_MIN_BALLS = 24 // a competition split is shown only with at least this many high-pressure balls
